void ShapeEstimationNode::callback(
  const AUTOWARE_MESSAGE_CONST_SHARED_PTR(DetectedObjectsWithFeature) & input_msg)
{
  stop_watch_ptr_->toc("processing_time", true);
  // Guard
  if (pub_->get_subscription_count() < 1) {
    return;
  }

  // Create output msg
  auto output_msg = ALLOCATE_OUTPUT_MESSAGE_UNIQUE(pub_);
  output_msg->header = input_msg->header;

  // Create ml model input batch
  DetectedObjectsWithFeature input_trt_batch;

  // Estimate shape for each object and pack msg
  for (const auto & feature_object : input_msg->feature_objects) {
    const auto & object = feature_object.object;
    const auto label = get_label(object.classification);
    const auto is_vehicle = label_is_vehicle(label);
    const auto & feature = feature_object.feature;
    // convert ros to pcl
    pcl::PointCloud<pcl::PointXYZ>::Ptr cluster(new pcl::PointCloud<pcl::PointXYZ>);
    pcl::fromROSMsg(feature.cluster, *cluster);

    // check cluster data
    if (cluster->empty()) {
      continue;
    }

#ifdef USE_CUDA
    // If ml based shape estimation is enabled, add object to input batch and continue
    if (is_vehicle && use_ml_shape_estimation_ && cluster->size() > min_points_) {
      input_trt_batch.feature_objects.push_back(feature_object);
      continue;
    }
#endif

    // estimate shape and pose
    autoware_perception_msgs::msg::Shape shape;
    geometry_msgs::msg::Pose pose;
    boost::optional<ReferenceYawInfo> ref_yaw_info = boost::none;
    boost::optional<ReferenceShapeSizeInfo> ref_shape_size_info = boost::none;
    boost::optional<geometry_msgs::msg::Pose> ref_pose = boost::none;
    if (use_vehicle_reference_yaw_ && is_vehicle) {
      ref_yaw_info = ReferenceYawInfo{
        static_cast<float>(tf2::getYaw(object.kinematics.pose_with_covariance.pose.orientation)),
        autoware_utils::deg2rad(10)};
    }
    if (use_vehicle_reference_shape_size_ && is_vehicle) {
      ref_shape_size_info = ReferenceShapeSizeInfo{object.shape, ReferenceShapeSizeInfo::Mode::Min};
    }
    const bool estimated_success = estimator_->estimateShapeAndPose(
      label, *cluster, ref_yaw_info, ref_shape_size_info, ref_pose, shape, pose);

    // If the shape estimation fails, change to Unknown object.
    if (!fix_filtered_objects_label_to_unknown_ && !estimated_success) {
      continue;
    }
    output_msg->feature_objects.push_back(feature_object);
    if (!estimated_success) {
      output_msg->feature_objects.back().object.classification.front().label = Label::UNKNOWN;
    }

    output_msg->feature_objects.back().object.shape = shape;
    output_msg->feature_objects.back().object.kinematics.pose_with_covariance.pose = pose;
  }

#ifdef USE_CUDA
  DetectedObjectsWithFeature output_model;
  if (use_ml_shape_estimation_ && !input_trt_batch.feature_objects.empty()) {
    tensorrt_shape_estimator_->inference(input_trt_batch, output_model);
  }
  for (auto & feature_object : output_model.feature_objects) {
    output_msg->feature_objects.push_back(feature_object);
  }
#endif

  // Publish
  const auto header_stamp = output_msg->header.stamp;
  pub_->publish(std::move(output_msg));
  published_time_publisher_->publish_if_subscribed(pub_, header_stamp);
  processing_time_publisher_->publish<autoware_internal_debug_msgs::msg::Float64Stamped>(
    "debug/cyclic_time_ms", stop_watch_ptr_->toc("cyclic_time", true));
  processing_time_publisher_->publish<autoware_internal_debug_msgs::msg::Float64Stamped>(
    "debug/processing_time_ms", stop_watch_ptr_->toc("processing_time", true));
}

bool ShapeEstimator::estimateShapeAndPose(
  const uint8_t label, const pcl::PointCloud<pcl::PointXYZ> & cluster,
  const boost::optional<ReferenceYawInfo> & ref_yaw_info,
  const boost::optional<ReferenceShapeSizeInfo> & ref_shape_size_info,
  const boost::optional<geometry_msgs::msg::Pose> & ref_pose,
  autoware_perception_msgs::msg::Shape & shape_output, geometry_msgs::msg::Pose & pose_output)
{
  autoware_perception_msgs::msg::Shape shape;
  geometry_msgs::msg::Pose pose;
  // estimate shape
  bool reverse_to_unknown = false;
  if (!estimateOriginalShapeAndPose(label, cluster, ref_yaw_info, shape, pose)) {
    reverse_to_unknown = true;
  }

  // rule based filter
  if (use_filter_) {
    if (!applyFilter(label, shape, pose)) {
      reverse_to_unknown = true;
    }
  }

  // rule based corrector
  if (use_corrector_) {
    bool use_reference_yaw = ref_yaw_info ? true : false;
    if (!applyCorrector(label, use_reference_yaw, ref_shape_size_info, ref_pose, shape, pose)) {
      reverse_to_unknown = true;
    }
  }
  if (reverse_to_unknown) {
    estimateOriginalShapeAndPose(Label::UNKNOWN, cluster, ref_yaw_info, shape, pose);
    shape_output = shape;
    pose_output = pose;
    return false;
  }
  shape_output = shape;
  pose_output = pose;
  return true;
}

bool ShapeEstimator::estimateOriginalShapeAndPose(
  const uint8_t label, const pcl::PointCloud<pcl::PointXYZ> & cluster,
  const boost::optional<ReferenceYawInfo> & ref_yaw_info,
  autoware_perception_msgs::msg::Shape & shape_output, geometry_msgs::msg::Pose & pose_output)
{
  // estimate shape
  std::unique_ptr<model::ShapeEstimationModelInterface> model_ptr;
  if (
    label == Label::CAR || label == Label::TRUCK || label == Label::BUS ||
    label == Label::TRAILER || label == Label::MOTORCYCLE || label == Label::BICYCLE) {
    model_ptr.reset(new model::BoundingBoxShapeModel(ref_yaw_info, use_boost_bbox_optimizer_));
  } else if (label == Label::PEDESTRIAN) {
    model_ptr.reset(new model::CylinderShapeModel());
  } else {
    model_ptr.reset(new model::ConvexHullShapeModel());
  }

  return model_ptr->estimate(cluster, shape_output, pose_output);
}

bool CylinderShapeModel::estimate(
  const pcl::PointCloud<pcl::PointXYZ> & cluster,
  autoware_perception_msgs::msg::Shape & shape_output, geometry_msgs::msg::Pose & pose_output)
{
  // calc min and max z for cylinder length
  float min_z = cluster.empty() ? 0.0 : cluster.at(0).z;
  float max_z = cluster.empty() ? 0.0 : cluster.at(0).z;
  for (const auto & point : cluster) {
    min_z = std::min(point.z, min_z);
    max_z = std::max(point.z, max_z);
  }

  // calc circumscribed circle on x-y plane
  cv::Mat_<float> cv_points(static_cast<int>(cluster.size()), 2);
  for (size_t i = 0; i < cluster.size(); ++i) {
    cv_points(i, 0) = cluster.at(i).x;  // x
    cv_points(i, 1) = cluster.at(i).y;  // y
  }
  cv::Point2f center;
  float radius;
  cv::minEnclosingCircle(cv::Mat(cv_points).reshape(2), center, radius);
  constexpr float ep = 0.001;
  radius = std::max(radius, static_cast<float>(ep));

  shape_output.type = autoware_perception_msgs::msg::Shape::CYLINDER;
  shape_output.dimensions.x = static_cast<float>(radius) * 2.0;
  shape_output.dimensions.y = static_cast<float>(radius) * 2.0;
  shape_output.dimensions.z = std::max((max_z - min_z), ep);
  pose_output.position.x = center.x;
  pose_output.position.y = center.y;
  pose_output.position.z = min_z + shape_output.dimensions.z * 0.5;
  pose_output.orientation.x = 0;
  pose_output.orientation.y = 0;
  pose_output.orientation.z = 0;
  pose_output.orientation.w = 1;
  return true;
}

bool ShapeEstimator::applyFilter(
  const uint8_t label, const autoware_perception_msgs::msg::Shape & shape,
  const geometry_msgs::msg::Pose & pose)
{
  std::unique_ptr<filter::ShapeEstimationFilterInterface> filter_ptr;
  if (label == Label::CAR) {
    filter_ptr.reset(new filter::CarFilter);
  } else if (label == Label::BUS) {
    filter_ptr.reset(new filter::BusFilter);
  } else if (label == Label::TRUCK) {
    filter_ptr.reset(new filter::TruckFilter);
  } else if (label == Label::TRAILER) {
    filter_ptr.reset(new filter::TrailerFilter);
  } else {
    filter_ptr.reset(new filter::NoFilter);
  }

  return filter_ptr->filter(shape, pose);
}

bool BusFilter::filter(
  const autoware_perception_msgs::msg::Shape & shape,
  [[maybe_unused]] const geometry_msgs::msg::Pose & pose)
{
  constexpr float min_width = 2.0;
  constexpr float max_width = 3.2;
  constexpr float max_length = 17.0;
  return utils::filterVehicleBoundingBox(shape, min_width, max_width, max_length);
}

bool filterVehicleBoundingBox(
  const autoware_perception_msgs::msg::Shape & shape, const float min_width, const float max_width,
  const float max_length)
{
  const float x = shape.dimensions.x;
  const float y = shape.dimensions.y;
  const float s = x * y;

  if (shape.type != autoware_perception_msgs::msg::Shape::BOUNDING_BOX) {
    return true;
  }
  if (x < min_width && y < min_width) {
    return false;
  }
  if (max_width < x && max_width < y) {
    return false;
  }

  if (max_length < x || max_length < y) {
    return false;
  }

  if (max_length * max_width < s) {
    return false;
  }
  return true;
}

bool ShapeEstimator::applyCorrector(
  const uint8_t label, const bool use_reference_yaw,
  const boost::optional<ReferenceShapeSizeInfo> & ref_shape_size_info,
  const boost::optional<geometry_msgs::msg::Pose> & ref_pose,
  autoware_perception_msgs::msg::Shape & shape, geometry_msgs::msg::Pose & pose)
{
  std::unique_ptr<corrector::ShapeEstimationCorrectorInterface> corrector_ptr;

  if (ref_shape_size_info && use_reference_yaw) {
    if (ref_pose) {
      corrector_ptr.reset(new corrector::ReferenceObjectBasedVehicleCorrector(
        ref_shape_size_info.get(), ref_pose.get()));
    } else {
      corrector_ptr.reset(
        new corrector::ReferenceShapeBasedVehicleCorrector(ref_shape_size_info.get()));
    }
  } else if (label == Label::CAR) {
    corrector_ptr.reset(new corrector::CarCorrector(use_reference_yaw));
  } else if (label == Label::BUS) {
    corrector_ptr.reset(new corrector::BusCorrector(use_reference_yaw));
  } else if (label == Label::TRUCK) {
    corrector_ptr.reset(new corrector::TruckCorrector(use_reference_yaw));
  } else if (label == Label::TRAILER) {
    corrector_ptr.reset(new corrector::TrailerCorrector(use_reference_yaw));
  } else if (label == Label::MOTORCYCLE || label == Label::BICYCLE) {
    corrector_ptr.reset(new corrector::BicycleCorrector(use_reference_yaw));
  } else {
    corrector_ptr.reset(new corrector::NoCorrector);
  }

  return corrector_ptr->correct(shape, pose);
}

bool ReferenceObjectBasedVehicleCorrector::correct(
  autoware_perception_msgs::msg::Shape & shape, geometry_msgs::msg::Pose & pose)
{
  return corrector_utils::correctWithReferenceShapeAndPose(
    ref_shape_size_info_, ref_pose_, shape, pose);
}

bool correctWithReferenceShapeAndPose(
  const ReferenceShapeSizeInfo & ref_shape_size_info, const geometry_msgs::msg::Pose & ref_pose,
  autoware_perception_msgs::msg::Shape & shape, geometry_msgs::msg::Pose & pose)
{
  /*
  c1 is farthest point from ref_pose and other points are arranged like below
  c is center of bounding box
         width
         4---2
         |   |
  length | c | → ey
         |   |
         3---1
           ↓
           ex
 */

  Eigen::Affine3d base2obj_transform;
  tf2::fromMsg(pose, base2obj_transform);

  Eigen::Vector3d local_c1 = Eigen::Vector3d::Zero();
  Eigen::Vector3d ref_center = Eigen::Vector3d(ref_pose.position.x, ref_pose.position.y, 0.0);
  // local points
  std::vector<Eigen::Vector3d> v_points;
  v_points.push_back(Eigen::Vector3d(shape.dimensions.x * 0.5, shape.dimensions.y * 0.5, 0.0));
  v_points.push_back(Eigen::Vector3d(-shape.dimensions.x * 0.5, shape.dimensions.y * 0.5, 0.0));
  v_points.push_back(Eigen::Vector3d(shape.dimensions.x * 0.5, -shape.dimensions.y * 0.5, 0.0));
  v_points.push_back(Eigen::Vector3d(-shape.dimensions.x * 0.5, -shape.dimensions.y * 0.5, 0.0));

  double max_dist = -1.0;
  // search the most distant index (c1) from the reference object's center
  for (std::size_t i = 0; i < v_points.size(); ++i) {
    const double tmp_dist = ((base2obj_transform * v_points[i]) - ref_center).squaredNorm();
    if (tmp_dist > max_dist) {
      local_c1 = v_points[i];
      max_dist = tmp_dist;
    }
  }

  Eigen::Vector3d ex = (Eigen::Vector3d(local_c1.x() / std::abs(local_c1.x()), 0, 0));
  Eigen::Vector3d ey = (Eigen::Vector3d(0, local_c1.y() / std::abs(local_c1.y()), 0));

  double length;
  if (
    ref_shape_size_info.mode == ReferenceShapeSizeInfo::Mode::Min &&
    ref_shape_size_info.shape.dimensions.x < shape.dimensions.x) {
    length = shape.dimensions.x;
  } else {
    length = ref_shape_size_info.shape.dimensions.x;
  }

  double width;
  if (
    ref_shape_size_info.mode == ReferenceShapeSizeInfo::Mode::Min &&
    ref_shape_size_info.shape.dimensions.y < shape.dimensions.y) {
    width = shape.dimensions.y;
  } else {
    width = ref_shape_size_info.shape.dimensions.y;
  }

  shape.dimensions.x = length;
  shape.dimensions.y = width;

  // compute a new center with correction vector
  Eigen::Vector3d new_centroid =
    (base2obj_transform * local_c1) -
    (base2obj_transform.rotation() * (ex * length * 0.5 + ey * width * 0.5));
  pose.position.x = new_centroid.x();
  pose.position.y = new_centroid.y();
  pose.position.z = new_centroid.z();

  return true;
}

bool TrtShapeEstimator::inference(
  const DetectedObjectsWithFeature & input, DetectedObjectsWithFeature & output)
{
  bool result = false;

  for (size_t i = 0; i < input.feature_objects.size(); i += batch_size_) {
    DetectedObjectsWithFeature input_batch;
    input_batch.header = input.header;

    for (size_t j = 0; j < batch_size_ && (i + j) < input.feature_objects.size(); ++j) {
      input_batch.feature_objects.push_back(input.feature_objects[i + j]);
    }

    preprocess(input_batch);
    DetectedObjectsWithFeature output_batch;
    result = feed_forward_and_decode(input_batch, output_batch);

    output.feature_objects.insert(
      output.feature_objects.end(), output_batch.feature_objects.begin(),
      output_batch.feature_objects.end());
  }

  return result;
}

void TrtShapeEstimator::preprocess(const DetectedObjectsWithFeature & input)
{
  auto input_dims_pc = trt_common_->getTensorShape(0);
  int batch_size = static_cast<int>(input.feature_objects.size());

  const auto input_chan = static_cast<float>(input_dims_pc.d[1]);
  const auto input_pc_size = static_cast<float>(input_dims_pc.d[2]);

  auto input_dims_one_hot = trt_common_->getTensorShape(1);
  const auto input_one_hot_size = static_cast<float>(input_dims_one_hot.d[1]);

  int volume_pc = batch_size * input_chan * input_pc_size;
  input_pc_h_.resize(volume_pc);

  int volume_one_hot = batch_size * input_one_hot_size;
  input_one_hot_h_.resize(volume_one_hot);

  // fill point cloud
  for (size_t i = 0; i < input.feature_objects.size(); i++) {
    const auto & feature_object = input.feature_objects[i];

    int point_size_of_cloud =
      feature_object.feature.cluster.width * feature_object.feature.cluster.height;

    if (point_size_of_cloud <= input_pc_size) {
      int offset = 0;
      for (sensor_msgs::PointCloud2ConstIterator<float> x_iter(feature_object.feature.cluster, "x"),
           y_iter(feature_object.feature.cluster, "y"), z_iter(feature_object.feature.cluster, "z");
           x_iter != x_iter.end(); ++x_iter, ++y_iter, ++z_iter) {
        input_pc_h_[i * input_chan * input_pc_size + 0 + offset] = -1 * (*y_iter);
        input_pc_h_[i * input_chan * input_pc_size + 512 + offset] = -1 * (*z_iter);
        input_pc_h_[i * input_chan * input_pc_size + 1024 + offset] = *x_iter;
        offset++;
      }

      int iter_count = static_cast<int>(input_pc_size) / point_size_of_cloud;
      int remaining_points_count = static_cast<int>(input_pc_size) % point_size_of_cloud;

      for (int j = 1; j < iter_count; j++) {
        for (int k = 0; k < point_size_of_cloud; k++) {
          input_pc_h_[i * input_chan * input_pc_size + 0 + j * point_size_of_cloud + k] =
            input_pc_h_[i * input_chan * input_pc_size + k];

          input_pc_h_[i * input_chan * input_pc_size + 512 + j * point_size_of_cloud + k] =
            input_pc_h_[i * input_chan * input_pc_size + 512 + k];

          input_pc_h_[i * input_chan * input_pc_size + 1024 + j * point_size_of_cloud + k] =
            input_pc_h_[i * input_chan * input_pc_size + 1024 + k];
        }
      }

      for (int j = 0; j < remaining_points_count; j++) {
        input_pc_h_[i * input_chan * input_pc_size + 0 + iter_count * point_size_of_cloud + j] =
          input_pc_h_[i * input_chan * input_pc_size + j];

        input_pc_h_[i * input_chan * input_pc_size + 512 + iter_count * point_size_of_cloud + j] =
          input_pc_h_[i * input_chan * input_pc_size + 512 + j];

        input_pc_h_[i * input_chan * input_pc_size + 1024 + iter_count * point_size_of_cloud + j] =
          input_pc_h_[i * input_chan * input_pc_size + 1024 + j];
      }

    } else {
      std::vector<float> sampled_points;
      std::vector<size_t> indices(
        feature_object.feature.cluster.width * feature_object.feature.cluster.height);
      std::iota(indices.begin(), indices.end(), 0);

      std::sample(
        indices.begin(), indices.end(), std::back_inserter(sampled_points), 512,
        std::mt19937{std::random_device{}()});

      // Create an iterator to read the points
      sensor_msgs::PointCloud2ConstIterator<float> iter_x(feature_object.feature.cluster, "x");
      sensor_msgs::PointCloud2ConstIterator<float> iter_y(feature_object.feature.cluster, "y");
      sensor_msgs::PointCloud2ConstIterator<float> iter_z(feature_object.feature.cluster, "z");

      int offset = 0;
      for (const auto & index : sampled_points) {
        auto idx = index * feature_object.feature.cluster.point_step / sizeof(float);
        input_pc_h_[i * input_chan * input_pc_size + 0 + offset] = (-1 * iter_y[idx]);
        input_pc_h_[i * input_chan * input_pc_size + 512 + offset] = (-1 * iter_z[idx]);
        input_pc_h_[i * input_chan * input_pc_size + 1024 + offset] = iter_x[idx];
        offset++;
      }
    }

    const auto & label = feature_object.object.classification.front().label;

    // Initialize all elements to 0.0f
    input_one_hot_h_[i * 4 + 0] = 0.0f;
    input_one_hot_h_[i * 4 + 1] = 0.0f;
    input_one_hot_h_[i * 4 + 2] = 0.0f;
    input_one_hot_h_[i * 4 + 3] = 0.0f;

    if (label == Label::CAR) {
      input_one_hot_h_[i * 4 + 0] = 1.0f;
    } else if (label == Label::TRUCK) {
      input_one_hot_h_[i * 4 + 1] = 1.0f;
    } else if (label == Label::BUS) {
      input_one_hot_h_[i * 4 + 2] = 1.0f;
    } else if (label == Label::TRAILER) {
      input_one_hot_h_[i * 4 + 3] = 1.0f;
    }
  }

  CHECK_CUDA_ERROR(cudaMemcpy(
    input_pc_d_.get(), input_pc_h_.data(), input_pc_h_.size() * sizeof(float),
    cudaMemcpyHostToDevice));
  CHECK_CUDA_ERROR(cudaMemcpy(
    input_one_hot_d_.get(), input_one_hot_h_.data(), input_one_hot_h_.size() * sizeof(float),
    cudaMemcpyHostToDevice));
}

nvinfer1::Dims TrtCommon::getTensorShape(const int32_t index) const
{
  if (!engine_) {
    logger_->log(
      nvinfer1::ILogger::Severity::kWARNING,
      "Engine is not initialized. Retrieving data from network");
    if (!network_) {
      logger_->log(nvinfer1::ILogger::Severity::kERROR, "Network is not initialized");
      return nvinfer1::Dims{};
    }
    auto num_inputs = network_->getNbInputs();
    auto num_outputs = network_->getNbOutputs();
    if (index < 0 || index >= num_inputs + num_outputs) {
      logger_->log(
        nvinfer1::ILogger::Severity::kERROR,
        "Invalid index for I/O tensor: %d. Total I/O tensors: %d", index, num_inputs + num_outputs);
      return nvinfer1::Dims{};
    }
    if (index < num_inputs) {
      return network_->getInput(index)->getDimensions();
    }
    return network_->getOutput(index - num_inputs)->getDimensions();
  }
  auto const & name = getIOTensorName(index);
  return getTensorShape(name);
}

nvinfer1::Dims TrtCommon::getTensorShape(const char * tensor_name) const
{
  if (!engine_) {
    logger_->log(nvinfer1::ILogger::Severity::kERROR, "Engine is not initialized");
    return nvinfer1::Dims{};
  }
  return engine_->getTensorShape(tensor_name);
}

bool TrtShapeEstimator::feed_forward_and_decode(
  const DetectedObjectsWithFeature & input, DetectedObjectsWithFeature & output)
{
  int batch_size = static_cast<int>(input.feature_objects.size());
  std::vector<void *> buffers = {
    input_pc_d_.get(), input_one_hot_d_.get(), out_s1center_prob_d_.get(), out_pred_prob_d_.get()};
  if (!trt_common_->setTensorsAddresses(buffers)) {
    return false;
  }
  trt_common_->enqueueV3(*stream_);

  CHECK_CUDA_ERROR(cudaMemcpyAsync(
    out_s1center_prob_h_.get(), out_s1center_prob_d_.get(), out_s1center_elem_num_ * sizeof(float),
    cudaMemcpyDeviceToHost, *stream_));

  CHECK_CUDA_ERROR(cudaMemcpyAsync(
    out_pred_prob_h_.get(), out_pred_prob_d_.get(), out_pred_elem_num_ * sizeof(float),
    cudaMemcpyDeviceToHost, *stream_));

  cudaStreamSynchronize(*stream_);

  float * out_stage1_net = out_s1center_prob_h_.get();
  float * out_pred_net = out_pred_prob_h_.get();

  output.feature_objects.resize(batch_size);
  for (int i = 0; i < batch_size; i++) {
    output.feature_objects.at(i) = input.feature_objects.at(i);

    autoware_perception_msgs::msg::Shape shape;
    geometry_msgs::msg::Pose pose;

    shape.type = autoware_perception_msgs::msg::Shape::BOUNDING_BOX;

    pose.position.x = out_stage1_net[i * out_s1center_elem_num_per_batch_ + 2] +
                      out_pred_net[i * out_pred_elem_num_per_batch_ + 2];
    pose.position.y =
      -(out_stage1_net[i * out_s1center_elem_num_per_batch_ + 0] +
        out_pred_net[i * out_pred_elem_num_per_batch_ + 0]);
    pose.position.z =
      -(out_stage1_net[i * out_s1center_elem_num_per_batch_ + 1] +
        out_pred_net[i * out_pred_elem_num_per_batch_ + 1]);

    int idx = 0;
    idx += 3;

    int NUM_HEADING_BIN = 12;
    int NUM_SIZE_CLUSTER = 8;

    int heading_idx = 0;
    float max = std::numeric_limits<float>::lowest();
    for (int j = idx; j < idx + NUM_HEADING_BIN; j++) {
      if (out_pred_net[i * out_pred_elem_num_per_batch_ + j] > max) {
        max = out_pred_net[i * out_pred_elem_num_per_batch_ + j];
        heading_idx = j - idx;
      }
    }

    idx += NUM_HEADING_BIN;

    float heading_residual =
      out_pred_net[i * out_pred_elem_num_per_batch_ + idx + heading_idx] * (M_PI / NUM_HEADING_BIN);

    idx += NUM_HEADING_BIN;

    float heading = class2angle(heading_idx, heading_residual, NUM_HEADING_BIN);

    tf2::Quaternion quaternion;
    quaternion.setRPY(0.0, 0.0, -M_PI / 2 - heading);

    pose.orientation.x = quaternion.x();
    pose.orientation.y = quaternion.y();
    pose.orientation.z = quaternion.z();
    pose.orientation.w = quaternion.w();

    int size_idx = 0;
    max = std::numeric_limits<float>::lowest();
    for (int j = idx; j < idx + NUM_SIZE_CLUSTER; j++) {
      if (out_pred_net[i * out_pred_elem_num_per_batch_ + j] > max) {
        max = out_pred_net[i * out_pred_elem_num_per_batch_ + j];
        size_idx = j - idx;
      }
    }

    idx += NUM_SIZE_CLUSTER;
    float x_size = out_pred_net[i * out_pred_elem_num_per_batch_ + idx + size_idx * 3] *
                     g_type_mean_size_[size_idx][0] +
                   g_type_mean_size_[size_idx][0];

    float y_size = out_pred_net[i * out_pred_elem_num_per_batch_ + idx + size_idx * 3 + 1] *
                     g_type_mean_size_[size_idx][1] +
                   g_type_mean_size_[size_idx][1];
    float z_size = out_pred_net[i * out_pred_elem_num_per_batch_ + idx + size_idx * 3 + 2] *
                     g_type_mean_size_[size_idx][2] +
                   g_type_mean_size_[size_idx][2];

    shape.dimensions.x = x_size;
    shape.dimensions.y = y_size;
    shape.dimensions.z = z_size;

    output.feature_objects.at(i).object.shape = shape;
    output.feature_objects.at(i).object.kinematics.pose_with_covariance.pose = pose;
  }

  return true;
}

bool TrtCommon::setTensorsAddresses(std::vector<void *> & tensors)
{
  bool success = true;
  for (std::size_t i = 0, e = tensors.size(); i < e; i++) {
    auto const name = getIOTensorName(i);
    success &= setTensorAddress(name, tensors.at(i));
  }
  return success;
}

const char * TrtCommon::getIOTensorName(const int32_t index) const
{
  if (!engine_) {
    logger_->log(
      nvinfer1::ILogger::Severity::kWARNING,
      "Engine is not initialized. Retrieving data from network");
    if (!network_) {
      logger_->log(nvinfer1::ILogger::Severity::kERROR, "Network is not initialized");
      return nullptr;
    }
    auto num_inputs = network_->getNbInputs();
    auto num_outputs = network_->getNbOutputs();
    if (index < 0 || index >= num_inputs + num_outputs) {
      logger_->log(
        nvinfer1::ILogger::Severity::kERROR,
        "Invalid index for I/O tensor: %d. Total I/O tensors: %d", index, num_inputs + num_outputs);
      return nullptr;
    }
    if (index < num_inputs) {
      return network_->getInput(index)->getName();
    }
    return network_->getOutput(index - num_inputs)->getName();
  }

  return engine_->getIOTensorName(index);
}

bool TrtCommon::setTensorAddress(const char * tensor_name, void * data)
{
  if (!context_) {
    logger_->log(nvinfer1::ILogger::Severity::kERROR, "Context is not initialized");
    return false;
  }
  auto success = context_->setTensorAddress(tensor_name, data);
  if (!success) {
    logger_->log(
      nvinfer1::ILogger::Severity::kERROR,
      "Failed to set tensor address for tensor: ", tensor_name);
  }
  return success;
}

bool TrtCommon::enqueueV3(cudaStream_t stream)
{
  if (!context_) {
    logger_->log(nvinfer1::ILogger::Severity::kERROR, "Context is not initialized");
    return false;
  }
  if (trt_config_->profile_per_layer) {
    auto inference_start = std::chrono::high_resolution_clock::now();
    auto success = context_->enqueueV3(stream);
    auto inference_end = std::chrono::high_resolution_clock::now();
    host_profiler_->reportLayerTime(
      "inference_host",
      std::chrono::duration<float, std::milli>(inference_end - inference_start).count());
    return success;
  }
  return context_->enqueueV3(stream);
}

double TrtShapeEstimator::class2angle(int pred_cls, double residual, int num_class)
{
  double angle_per_class = 2.0 * M_PI / static_cast<double>(num_class);
  double angle_center = static_cast<double>(pred_cls) * angle_per_class;
  double angle = angle_center + residual;

  // Adjust angle to be within the range [-pi, pi]
  while (angle > M_PI) {
    angle -= 2.0 * M_PI;
  }
  while (angle < -M_PI) {
    angle += 2.0 * M_PI;
  }
  return angle;
};
